    function requestNotionConflict(conflicts,options){if(pendingNotionConflict)resolveNotionConflict(null);var opts=options||{},leftValue=opts.leftValue||'notion',rightValue=opts.rightValue||'study-hard',leftLabel=opts.leftLabel||'현재 Notion',rightLabel=opts.rightLabel||'변경될 Study Hard';notionConflictRecords={};notionConflictDrafts={};notionConflictBlockChoices={};(conflicts||[]).forEach(function(conflict){notionConflictRecords[conflict.sectionId]=conflict;});var list=document.getElementById('notionConflictList');list.innerHTML=(conflicts||[]).map(function(conflict,index){var id='notion-conflict-'+index,name='notion-conflict-choice-'+index;return'<section class="notionConflictCard" data-section-id="'+esc(conflict.sectionId)+'"><h3>'+esc(conflict.title||conflict.sectionId)+'</h3><div class="notionConflictCompare">'+blockDiffHtml(conflict,leftLabel,rightLabel)+'</div>'+conflictBlockWarning(conflict,rightLabel)+'<div class="notionConflictChoices"><label><input id="'+id+'-notion" type="radio" name="'+name+'" value="'+esc(leftValue)+'" checked> '+esc(leftLabel)+' 유지</label><label><input id="'+id+'-study" type="radio" name="'+name+'" value="'+esc(rightValue)+'"> '+esc(rightLabel)+' 적용</label><label><input id="'+id+'-manual" type="radio" name="'+name+'" value="manual"> 직접 정리</label></div><div class="notionManualEditor"><div class="notionManualTools"><button type="button" data-manual-base="merged">자동 병합 초안</button><button type="button" data-manual-base="left">'+esc(leftLabel)+' 블록으로 시작</button><button type="button" data-manual-base="right">'+esc(rightLabel)+' 블록으로 시작</button></div><div class="notionManualBlocks"></div></div></section>';}).join('');document.querySelectorAll('#notionConflictList input[type="radio"]').forEach(function(input){input.addEventListener('change',function(){var card=input.closest('[data-section-id]');if(input.value==='manual')renderManualBlockEditor(card,'merged');else card.classList.remove('manual');});});document.querySelectorAll('[data-manual-base]').forEach(function(button){button.addEventListener('click',function(){renderManualBlockEditor(button.closest('[data-section-id]'),button.dataset.manualBase);});});document.querySelectorAll('[data-diff-pick]').forEach(function(button){button.addEventListener('click',function(){var card=button.closest('[data-section-id]'),sectionId=card.dataset.sectionId,index=Number(button.dataset.diffIndex),choices=notionConflictBlockChoices[sectionId]||(notionConflictBlockChoices[sectionId]={});choices[index]=button.dataset.diffPick;chooseNotionConflict(card,'manual');card.querySelectorAll('[data-diff-index="'+index+'"]').forEach(function(item){item.classList.toggle('selected',item.dataset.diffPick===choices[index]);});});});document.getElementById('notionConflictTitle').textContent=opts.title||'Notion 변경 충돌 해소';document.querySelector('.notionConflictIntro').textContent=opts.intro||'두 변경이 같은 섹션에 있습니다. 동일 block은 접고 변경된 block은 −/＋로 비교합니다. 저장은 section 단위이며 직접 정리에서는 block별 수정·삭제·순서 변경이 가능합니다.';document.getElementById('notionConflictApply').textContent=opts.applyLabel||'선택 내용 적용';document.getElementById('notionConflictOverlay').hidden=false;document.getElementById('notionConflictAllNotion').textContent='모두 '+leftLabel+' 유지';document.getElementById('notionConflictAllStudy').textContent='모두 '+rightLabel+' 적용';document.getElementById('notionConflictAllNotion').onclick=function(){setAllNotionConflictChoices(leftValue);};document.getElementById('notionConflictAllStudy').onclick=function(){setAllNotionConflictChoices(rightValue);};document.getElementById('notionConflictAllManual').onclick=function(){setAllNotionConflictChoices('manual');};document.getElementById('notionConflictCancel').onclick=function(){resolveNotionConflict(null);};document.getElementById('notionConflictApply').onclick=function(){var resolution={};document.querySelectorAll('#notionConflictList [data-section-id]').forEach(function(card){var selected=card.querySelector('input:checked');if(!selected)return;resolution[card.dataset.sectionId]=selected.value==='manual'?{choice:'manual',blocks:collectManualBlocks(card)}:{choice:selected.value};});resolveNotionConflict(resolution);};setTimeout(function(){document.getElementById('notionConflictApply').focus();},0);return new Promise(function(resolve){pendingNotionConflict=resolve;});}
    async function exportNotion(){var button=document.getElementById('notionExportButton');button.disabled=true;setExportStatus('시각 자료를 준비하는 중...');try{var diagramAssets=await collectNotionDiagramAssets(),resolution=null,result;while(true){setExportStatus(resolution?'충돌 선택대로 다시 동기화하는 중...':'Notion에 저장하는 중...');result=await post('/export/notion',{diagramAssets:diagramAssets,conflictResolution:resolution||undefined});if(result.status!=='conflict')break;setExportStatus('Notion 변경 충돌 · 선택 필요');resolution=await requestNotionConflict(result.conflicts||[]);if(!resolution){setExportStatus('Notion 저장 보류 · 수동 편집 유지');return;}}var importedSectionItems=Array.isArray(result.importedSections)?result.importedSections:[],importedSections=importedSectionItems.length,importedImages=importedSectionItems.reduce(function(count,section){return count+(Array.isArray(section.blocks)?section.blocks.filter(function(block){return block.type==='image';}).length:0);},0),importedSummary=importedSections||importedImages?'Notion에서 '+(importedSections?'섹션 '+importedSections+'개':'')+(importedSections&&importedImages?' · ':'')+(importedImages?'이미지 '+importedImages+'개':'')+' 가져옴 · ':'';var message=result.staleAfterSync?'Notion에는 revision '+result.syncedRevision+' 저장됨 · 현재 노트는 미저장':importedSummary+'revision '+result.syncedRevision+' 동기화됨';setExportStatus(message,safeUrl(result.pageUrl));}catch(error){setExportStatus('Notion 저장 실패');window.alert('Notion에 저장하지 못했습니다: '+error.message);}finally{button.disabled=false;}}
    function openHistoryPreview(id,revision){var overlay=document.getElementById('historyPreviewOverlay'),frame=document.getElementById('historyPreviewFrame');document.getElementById('historyPreviewTitle').textContent='revision '+revision+' · HTML 미리보기';frame.src='/history/'+encodeURIComponent(id)+'/html';overlay.hidden=false;document.getElementById('historyPreviewClose').focus();}
