    function requestHistoryRestore(revision){if(pendingHistoryRestore)resolveHistoryRestore(false);document.getElementById('historyRestoreMessage').textContent='revision '+revision+'의 학습노트를 현재 시점의 새 revision으로 복원합니다. 새 질문·첨부·보드 위치는 유지됩니다.';document.getElementById('historyRestoreConfirm').hidden=false;setTimeout(function(){document.getElementById('historyRestoreAccept').focus();},0);return new Promise(function(resolve){pendingHistoryRestore=resolve;});}
