    function requestWorkTransition(intent){if(pendingWorkTransition)resolveWorkTransition(false);var applying=intent==='apply-frame';document.getElementById('workTransitionTitle').textContent=applying?'현재 학습을 Frame에 반영':'작업 시작 준비';document.getElementById('workTransitionMessage').textContent=applying?'현재 Study Hard run 전체 변경을 Frame에 반영하도록 Pi에 요청합니다. 코드 구현은 시작하지 않습니다.':'Frame 상태를 확인하고 작업 시작 흐름으로 이동합니다. Frame 갱신이 필요하면 구현 전에 먼저 검토합니다.';document.getElementById('workTransitionAccept').textContent=applying?'Frame 반영 요청':'작업 시작 요청';document.getElementById('workTransitionConfirm').hidden=false;setTimeout(function(){document.getElementById('workTransitionAccept').focus();},0);return new Promise(function(resolve){pendingWorkTransition={intent:intent,resolve:resolve};});}
