    function renderHistory(entries){var target=document.getElementById('historyBody');target.innerHTML='<div class="callout info"><b>설명이 실제로 바뀐 시점만 저장합니다</b><p>질문·첨부·보드 위치는 유지하고, 학습노트와 연결된 Before/After flow만 과거 버전으로 복원합니다.</p></div>'+entries.map(function(entry){return'<div class="card historyItem"><div class="historyTitle"><b>revision '+esc(entry.revision)+'</b>'+(entry.current?'<span class="pill">현재</span>':'')+'</div><div class="small">'+esc(new Date(entry.savedAt).toLocaleString('ko-KR'))+' · 섹션 '+esc(entry.sectionCount)+'개</div><div class="historyActions"><button data-history-preview="'+esc(entry.id)+'" data-history-revision="'+esc(entry.revision)+'">HTML 미리보기</button>'+(entry.current?'':'<button class="primary" data-history-restore="'+esc(entry.id)+'" data-history-revision="'+esc(entry.revision)+'">이 버전 복원</button>')+'</div></div>';}).join('');document.querySelectorAll('[data-history-preview]').forEach(function(button){button.addEventListener('click',function(){openHistoryPreview(button.dataset.historyPreview,button.dataset.historyRevision);});});document.querySelectorAll('[data-history-restore]').forEach(function(button){button.addEventListener('click',async function(){var accepted=await requestHistoryRestore(button.dataset.historyRevision);if(!accepted)return;button.disabled=true;setExportStatus('revision '+button.dataset.historyRevision+' 복원 중...');try{var result=await post('/history/restore',{id:button.dataset.historyRestore});setExportStatus('revision '+result.restoredFromRevision+'에서 복원됨');await loadHistory();}catch(error){setExportStatus('버전 복원 실패 · '+error.message);}finally{button.disabled=false;}});});}
    async function loadHistory(){var target=document.getElementById('historyBody');target.innerHTML='<p class="small">버전 기록을 불러오는 중...</p>';try{var response=await fetch('/history');if(!response.ok)throw new Error(await response.text());var result=await response.json();renderHistory(result.entries||[]);}catch(error){target.innerHTML='<div class="callout warning"><b>버전 기록을 불러오지 못했습니다</b><p>'+esc(error.message)+'</p></div>';}}function openHistory(){closeDrawer('statusDrawer');openDrawer('historyDrawer');loadHistory();}function syncDrawerLayout(){var workspace=document.getElementById('workspace'),detail=document.getElementById('detailDrawer');workspace.classList.toggle('rightDrawerOpen',detail.classList.contains('open'));}function openDrawer(id){var drawer=document.getElementById(id);if(id==='detailDrawer'){document.getElementById('statusDrawer').classList.remove('open');document.getElementById('historyDrawer').classList.remove('open');}else{document.getElementById('detailDrawer').classList.remove('open');}drawer.classList.add('open');syncDrawerLayout();}function closeDrawer(id){document.getElementById(id).classList.remove('open');syncDrawerLayout();}function setSurface(surface,persist){if(surface==='review'&&!state.metaReview)surface='note';if(surface!=='review'&&metaReviewPollTimer){clearTimeout(metaReviewPollTimer);metaReviewPollTimer=null;}state.activeSurface=surface;document.querySelectorAll('[data-surface]').forEach(function(b){b.classList.toggle('active',b.dataset.surface===surface);});['map','flow','note','review'].forEach(function(n){document.getElementById(n+'Surface').classList.toggle('active',n===surface);});if(surface==='map'){closeDrawer('detailDrawer');setTimeout(renderMap,0);}if(surface==='flow')renderFlow();if(surface==='note')renderNote();if(surface==='review')loadMetaReview();if(persist)post('/workspace',{activeSurface:surface}).catch(console.warn);}
    function compactThoughtText(value,maxLength){var text=String(value||'').replace(/\s+/g,' ').trim(),limit=Number(maxLength||180);return text.length>limit?text.slice(0,limit-1)+'…':text;}
    function noteBlockLabel(block){if(!block)return'과거 노트 블록';var value=block.title||block.text||block.body||(block.code&&block.code.reference&&block.code.reference.path)||(block.type==='table'?'표':block.type==='list'?'목록':block.type==='code'?'코드':block.type==='visual'?'시각 자료':block.id);return compactThoughtText(value,90)||block.id;}
