    function metaReviewExplanationHtml(hunk,file){return'<aside class="reviewExplanation reviewSelectable" data-review-hunk="'+esc(hunk.id)+'" data-review-evidence="'+esc((hunk.evidenceIds||[]).join(','))+'" data-review-file="'+esc(file.id)+'" data-review-path="'+esc(file.path)+'" data-review-select-kind="hunk" data-review-select-id="'+esc(hunk.id)+'" data-review-select-label="'+esc('설명 블록 · '+hunk.title)+'"><h4>📖 '+esc(hunk.title)+' <span class="reviewStatus">'+esc(hunk.status||'new')+'</span></h4><dl><dt>무엇이 바뀌었나</dt><dd>'+esc(hunk.whatChanged)+'</dd><dt>왜 바뀌었나</dt><dd>'+esc(hunk.why)+'</dd><dt>코드·도메인 근거</dt><dd>'+esc(hunk.evidence)+'</dd><dt>이 레이어의 책임</dt><dd>'+esc(hunk.responsibility)+'</dd><dt>호출·데이터 영향</dt><dd>'+esc(hunk.flowImpact)+'</dd>'+(hunk.concepts&&hunk.concepts.length?'<dt>사용된 개념</dt><dd>'+esc(hunk.concepts.join(' · '))+'</dd>':'')+(hunk.uncertainty?'<dt>❓ 확인 필요</dt><dd>'+esc(hunk.uncertainty)+'</dd>':'')+'</dl></aside>';}
    function metaReviewFindingHtml(card,file){var draft=card.editedReviewDraft||card.reviewDraft||'';return'<aside class="reviewFinding reviewSelectable" data-review-card="'+esc(card.id)+'" data-review-evidence="'+esc((card.evidenceIds||[]).join(','))+'" data-review-file="'+esc(file.id)+'" data-review-path="'+esc(file.path)+'" data-review-select-kind="card" data-review-select-id="'+esc(card.id)+'" data-review-select-label="'+esc('리뷰 포인트 · '+card.id+' · '+card.title)+'"><h4>⚠️ '+esc(card.id)+' · '+esc(card.title)+'</h4><div class="small">'+esc(card.strength)+' · confidence '+esc(card.confidence)+(card.decision?' · '+esc(card.decision):'')+'</div><div class="reviewFindingDraft">'+esc(draft)+'</div><p>'+esc(card.explanation||'')+'</p><details><summary>메타적 관점과 인간 리뷰 precedent</summary><p>'+esc(card.meta&&card.meta.summary||'')+'</p>'+((card.precedents||[]).map(function(item){return'<p><a href="'+esc(item.url)+'" target="_blank" rel="noreferrer">'+esc(item.label)+'</a> · '+esc(item.similarity||'')+(item.difference?' · 차이: '+esc(item.difference):'')+'</p>';}).join(''))+'<label>리뷰 문구 수정<textarea data-review-draft>'+esc(draft)+'</textarea></label></details><div class="reviewActions"><button class="primary" data-review-decision="review-only">리뷰 채택</button><button data-review-decision="review-with-meta">메타 포함</button><button data-review-decision="edit">수정 저장</button><button data-review-decision="follow-up">후속</button><button data-review-decision="hold">보류</button><button data-review-decision="dismiss">폐기</button></div></aside>';}
    function metaReviewFileHtml(file,index){var guide=metaReviewGuideFor(file.path),hunks=guide&&guide.hunks||[],cards=(metaReviewState.cards||[]).filter(function(card){return card.code&&card.code.path===file.path;}),afterLine=new Map();hunks.forEach(function(hunk){var anchor=(hunk.evidenceIds||[]).slice(-1)[0];if(anchor)afterLine.set(anchor,[...(afterLine.get(anchor)||[]),metaReviewExplanationHtml(hunk,file)]);});cards.forEach(function(card){var anchor=(card.evidenceIds||[]).slice(-1)[0];if(anchor)afterLine.set(anchor,[...(afterLine.get(anchor)||[]),metaReviewFindingHtml(card,file)]);});var diff=(file.lines||[]).map(function(line){var lineNumber=line.newLine==null?line.oldLine:line.newLine,label='코드 줄 · '+file.path+(lineNumber==null?'':':'+lineNumber),html='<div class="reviewLine reviewSelectable '+esc(metaReviewLineClass(line.kind))+'" data-review-line="'+esc(line.id)+'" data-review-evidence="'+esc(line.id)+'" data-review-file="'+esc(file.id)+'" data-review-path="'+esc(file.path)+'" data-review-select-kind="line" data-review-select-id="'+esc(line.id)+'" data-review-select-label="'+esc(label)+'"><span class="reviewLineNo">'+esc(line.oldLine==null?'':line.oldLine)+'</span><span class="reviewLineNo">'+esc(line.newLine==null?'':line.newLine)+'</span><span class="reviewLineCode">'+esc(line.text)+'</span></div>';return html+(afterLine.get(line.id)||[]).join('');}).join('');return'<details class="reviewFile" open data-review-file-section="'+esc(file.id)+'"><summary><span>'+String(index+1).padStart(2,'0')+' · '+esc(file.path)+'</span><span>+'+esc(file.additions)+' / -'+esc(file.deletions)+'</span></summary><div class="reviewFileIntro reviewSelectable" data-review-file="'+esc(file.id)+'" data-review-path="'+esc(file.path)+'" data-review-select-kind="file" data-review-select-id="'+esc(file.id)+'" data-review-select-label="'+esc('파일 · '+file.path)+'">'+(guide?'<p><b>파일 역할</b> · '+esc(guide.role)+'</p><p><b>이 PR에서 바뀐 이유</b> · '+esc(guide.changeReason)+'</p><p><b>호출·데이터 흐름</b> · '+esc(guide.flow)+'</p>'+(guide.impact?'<p><b>사용자·후속 영향</b> · '+esc(guide.impact)+'</p>':''):'<p>이 파일의 학습 설명을 생성하는 중입니다.</p>')+'</div><div class="reviewDiff">'+diff+'</div></details>';}
    function metaReviewContextKey(context){if(!context||context.scope==='session')return'session';return[context.scope,context.selectionKind||'',context.selectionId||'',context.cardId||'',context.fileId||'',(context.evidenceIds||[]).join(',')].join(':');}
