    async function askMetaReviewQuestion(){var input=document.getElementById('metaReviewQuestionInput'),button=document.getElementById('metaReviewQuestionSend'),status=document.getElementById('metaReviewQuestionStatus'),context=activeMetaReviewQuestionContext(),draftKey=metaReviewQuestionDraftKey(context),question=String(input&&input.value||'').trim();if(!question||!button||button.disabled)return;button.disabled=true;status.textContent='같은 Pi 세션에 전달 중…';try{var result=await post('/meta-review/ask',Object.assign({question:question},metaReviewQuestionPayload(context)));metaReviewQuestionDrafts[draftKey]='';if(result.question)metaReviewState.questions=(metaReviewState.questions||[]).filter(function(item){return item.id!==result.question.id;}).concat([result.question]);renderMetaReviewDetail();await loadMetaReview(true);}catch(error){metaReviewQuestionDrafts[draftKey]=question;var currentInput=document.getElementById('metaReviewQuestionInput'),currentStatus=document.getElementById('metaReviewQuestionStatus');if(currentInput&&!currentInput.value)currentInput.value=question;if(currentStatus)currentStatus.textContent='실패: '+error.message;}finally{var currentButton=document.getElementById('metaReviewQuestionSend');if(currentButton)currentButton.disabled=false;}}
