    function thoughtGroups(){var byBlock=new Map();thoughtQuestions().forEach(function(q){var items=byBlock.get(q.targetNoteBlockId)||[];items.push(q);byBlock.set(q.targetNoteBlockId,items);});var groups=[],seen=new Set(),documentState=state.noteDocument||{sections:[]};(documentState.sections||[]).forEach(function(section){var blocks=[];(section.blocks||[]).forEach(function(block){var questions=(byBlock.get(block.id)||[]).filter(function(q){return thoughtFilter==='all'||thoughtQuestionCategory(q)===thoughtFilter;});seen.add(block.id);if(questions.length)blocks.push({id:block.id,label:noteBlockLabel(block),excerpt:noteBlockExcerpt(block),exists:true,questions:questions});});if(blocks.length)groups.push({id:section.id,title:section.title,blocks:blocks});});var archived=[];byBlock.forEach(function(questions,blockId){if(seen.has(blockId))return;var visible=questions.filter(function(q){return thoughtFilter==='all'||thoughtQuestionCategory(q)===thoughtFilter;});if(visible.length)archived.push({id:blockId,label:blockId,excerpt:noteBlockExcerpt(null),exists:false,questions:visible});});if(archived.length)groups.push({id:'thought-archive',title:'과거 노트 블록',blocks:archived});return groups;}
