    function memoSummaryText(q){var source=String(q.resultSummary||q.feedback||'').trim();if(!source)return'Worker 답변을 기다리는 중입니다.';var tick=String.fromCharCode(96),fenced=new RegExp(tick.repeat(3)+'[\\s\\S]*?'+tick.repeat(3),'g');source=source.replace(/\[heestolee\.study-hard\.transcript\]/gi,' ').replace(fenced,' ').replace(/^(?:📚|📖|⚙️|🛠|⚠️)?\s*Study Hard[^\n]*$/gmi,' ').replace(/^\s*질문\s*:.*$/gmi,' ').replace(/^\s*(?:답변|원인)\s*:\s*/gmi,'').replace(/!\[([^\]]*)\]\([^)]+\)/g,'$1').replace(/\[([^\]]+)\]\([^)]+\)/g,'$1').replace(/^#{1,6}\s+/gm,'').replace(/^\s*(?:[-*+]\s+|\d+\.\s+)/gm,'').replace(/https?:\/\/\S+/g,'').replace(/[|*_~>]+/g,' ').replace(new RegExp(tick,'g'),' ').replace(/\s+/g,' ').trim();return compactThoughtText(source,180)||'대화 결과를 열어 확인하세요.';}
    function legacyQuestionText(value,maxLength){var source=String(value||'').trim(),marker='[heestolee.study-hard.transcript]',markerIndex=source.indexOf(marker);if(markerIndex>=0){var prefix=source.slice(0,markerIndex).replace(/[\s([{,:;·\-–—/]+$/g,'').trim(),questionMatch=source.slice(markerIndex).match(/(?:^|\s)질문\s*:\s*([\s\S]*?)(?=\s+답변\s*:|$)/i);source=prefix||(questionMatch&&questionMatch[1]||'').trim();}source=source.replace(/\[heestolee\.study-hard\.transcript\]/gi,' ').replace(/\s+/g,' ').trim();return maxLength?compactThoughtText(source,maxLength):source;}
    function memoQuestionText(q){return legacyQuestionText(q&&q.question,180)||'질문';}
    function thoughtQuestionCardHtml(q,block){var category=thoughtQuestionCategory(q),question=memoQuestionText(q),summary=memoSummaryText(q),expandable=!!String(q.feedback||'').trim(),expanded=expandable&&expandedThoughtQuestionIds.has(q.id),meta=[q.id,q.workerRunId?'worker #'+q.workerRunId:'',q.createdAt?new Date(q.createdAt).toLocaleString('ko-KR'):'' ].filter(Boolean).join(' · '),body=expanded?'<div class="thoughtMemoFull conversationMarkdown">'+renderConversationAnswer(q.feedback)+'</div>':'<p class="thoughtMemoSummary">'+esc(summary)+'</p>',hint=expandable?'<span class="thoughtMemoToggleHint">'+(expanded?'답변 접기 ▲':'답변 펼치기 ▼')+'</span>':'',navigation=(block.exists?'<button data-open-note-block="'+esc(q.targetNoteBlockId)+'">노트 보기</button>':'<button disabled>과거 블록</button>')+'<button class="primary" data-open-thought-question="'+esc(q.id)+'" data-open-note-block="'+esc(q.targetNoteBlockId)+'">대화 보기</button>';return'<article class="thoughtMemo '+category+' '+(expandable?'expandable ':'')+(expanded?'expanded ':'')+(thoughtFocusBlockId===block.id?'focus':'')+'" data-thought-question="'+esc(q.id)+'" data-thought-block="'+esc(block.id)+'"'+(expandable?' data-toggle-thought-question="'+esc(q.id)+'" tabindex="0" aria-expanded="'+expanded+'"':'')+'><div class="thoughtMemoHeader"><span class="thoughtMemoBlock">'+esc(block.exists?block.label:'과거 · '+block.label)+'</span><span class="thoughtState '+category+'">'+esc(thoughtStateLabel(q))+'</span></div><h3>'+esc(question)+'</h3>'+body+'<div class="thoughtMemoMeta"><span>'+esc(meta)+'</span>'+hint+'</div><div class="thoughtQuestionActions">'+navigation+'</div></article>';}
