    function renderBreadcrumb(){var counts=thoughtCounts();document.getElementById('breadcrumb').innerHTML='<b>생각 보드</b> · 노트 블록에서 나눈 질문과 worker 반영 결과를 다시 찾습니다. · 전체 '+esc(counts.all)+' · 미해결 '+esc(counts.unresolved);}function actorLabel(flow,id){var a=(flow.actors||[]).find(function(x){return x.id===id;});return a?a.label:id;}function selectedFlow(){return(state.flows||[]).find(function(f){return f.id===state.selectedFlowId})||(state.flows||[])[0]||null;}
